/* Alternatives: registering what an agent generated (an imported zip or folder), the stamp
   that says a slot's list changed, where an alternative's `local` is measured from, and
   turning one imported geometry into an option.
   Needs three (Matrix4), features/slot-state.js and features/slot-anchors.js. */

import { Matrix4, Vector3 } from 'three';
import { isObj, clone, need } from './slot-state.js';
import { anchorOf, geometryBBox, geometryStats, slug } from './slot-anchors.js';

/**
 * Alternatives generated by an agent, as read from an imported zip or folder.  Each entry
 * is a `rps/alternative@1` meta.json plus wherever its geometry came from.
 * @param {Array<object>} list
 * @returns {{added:number, slots:string[], warnings:string[]}}
 */
export function registerAlternatives(list, inst, opts = {}) {
  const I = need(inst);
  const warn = [];
  const touched = new Set();
  const groups = Object.create(null);
  /* The slots this call speaks for: a slot that was asked about and came back empty is
     cleared, not left showing a deleted card.  `{slot}` / `{slots:[…]}` name them; `{replaceAll:true}` (or `{slots:'*'}`) means
     "this list is the complete answer for every slot". */
  const asked = opts.slots === '*' || opts.replaceAll ? I.order
    : (Array.isArray(opts.slots) ? opts.slots : (opts.slot ? [opts.slot] : []));
  for (const sid of asked) {
    if (!I.slots[sid]) { warn.push(`alternatives requested for unknown slot "${sid}"`); continue; }
    groups[sid] = [];
    touched.add(sid);
  }
  for (const raw of list || []) {
    if (!isObj(raw)) continue;
    const sid = raw.slot || (raw.meta && raw.meta.slot);
    if (!sid) { warn.push('alternative without a "slot" ignored'); continue; }
    if (!I.slots[sid]) { warn.push(`alternative for unknown slot "${sid}" ignored`); continue; }
    const id = String(raw.id || raw.alt_id || raw.dir || raw.label || 'alt').trim();
    (groups[sid] = groups[sid] || []).push({
      id: 'alt:' + id, altId: id, slot: sid,
      label: raw.label || id, kind: 'alternative', group: 'agent',
      source: raw.source || 'inbox',
      frame: raw.frame || 'robot',
      local: Array.isArray(raw.local) && raw.local.length === 16 ? raw.local.slice() : null,
      printable: raw.printable !== false,
      print_orientation: Array.isArray(raw.print_orientation) ? raw.print_orientation.slice() : null,
      params: raw.params ? clone(raw.params) : {},
      cameras: raw.cameras ? clone(raw.cameras) : null,
      /* two lists, never one: `files` is the ROBOT-FRAME geometry the viewport draws,
         `printFiles` the bed-oriented plates the export ships (core/recent-store.js) */
      files: (raw.files || raw.stls || []).slice(),
      printFiles: (raw.print_files || raw.printFiles || []).slice(),
      meta: raw.meta || null,
      path: raw.path || raw.dir || null,
      mtime: raw.mtime || raw.modified || null,
      notes: raw.notes || raw.note || '',
      checked: raw.printcheck || null,
      shows: [], showSet: new Set(), replaces: [], attachments: [], requires: null,
      mount: I.slots[sid].anchor,
    });
    touched.add(sid);
  }
  for (const sid of touched) {
    if (groups[sid] && groups[sid].length) I.alternatives[sid] = groups[sid];
    else delete I.alternatives[sid];
  }
  return {
    added: Object.values(groups).reduce((n, a) => n + a.length, 0),
    slots: [...touched],
    cleared: [...touched].filter((sid) => !(groups[sid] && groups[sid].length)),
    warnings: warn,
  };
}

/**
 * `meta.frame` (core/recent-store.js readAlternativeFrom) is the whole rule, and it has two consumers
 * that must agree: the geometry of a workspace alternative and the camera block it
 * publishes.  Both resolve it here, pure, so the tests exercise the rule the page runs.
 *
 *   "robot"        `local` is already robot millimetres — what a generator naturally writes
 *   "slot_anchor"  `local` is relative to the slot's anchor frame (the package's
 *                  `frames.<slots.<id>.anchor>`), which is how an imported wrist mount rides
 *                  the arm
 *   "attachment"   the attached package's own frame; the slot anchor carries it, as before
 *
 * @param {string} slotId
 * @param {{frame?:string, local?:number[]|Matrix4}} alt
 * @param {object} inst   the `buildSlots()` instance
 * @returns {{link:string|null, frame:'robot'|'link', local:Matrix4, robot:Matrix4, source:string}}
 *   `local` is what a component's `local` must be set to and `frame`/`link` how to read it —
 *   `robot` is the same placement as one robot-frame matrix, for a readout or a test.
 */
export function alternativePlacement(slotId, alt, inst) {
  const I = need(inst);
  const model = I.model;
  const L = alt && alt.local;
  const local = (L && L.isMatrix4) ? L.clone()
    : (Array.isArray(L) && L.length === 16 ? new Matrix4().fromArray(L) : new Matrix4());
  const flat = (m) => ({ link: null, frame: 'robot', local: m, robot: m.clone(), source: 'robot' });
  if (!alt || (alt.frame || 'robot') === 'robot') return flat(local);
  let a = null;
  try { a = anchorOf(slotId, I); } catch (e) { a = null; }
  if (!a || !a.matrix) return flat(local);
  /* `anchorOf` answers in WORLD mm — it carries the driven base — while a component's `local`
     is read WITHOUT it (`robot-model._withBase`), so take the base back out before storing. */
  const unbase = (model.baseMatrix ? model.baseMatrix() : new Matrix4()).invert();
  const robot = unbase.clone().multiply(a.matrix).multiply(local);
  const parent = a.parent && a.parent !== 'world' ? a.parent : null;
  let fk = null;
  try { if (parent && model.hasLink && model.hasLink(parent)) fk = unbase.clone().multiply(model.fk(parent)); }
  catch (e) { fk = null; }
  if (!fk) return { link: null, frame: 'robot', local: robot, robot: robot.clone(), source: a.source || 'anchor' };
  return { link: parent, frame: 'link', local: fk.invert().multiply(robot), robot,
    source: `${a.source || 'anchor'} on ${parent}` };
}

/**
 * The carrier `features/cameras.js registerFrames()` must be given for an alternative's
 * `cameras` block: `'robot'` when `meta.frame` says robot, else the slot anchor's frame NAME.
 *
 * The name, never a baked matrix — `registerFrames` re-resolves a named carrier on every
 * `getPose()`, which is what keeps a wrist camera riding the arm.
 * @returns {string} 'robot' or the anchor frame name
 */
export function alternativeCameraFrame(slotId, alt, inst) {
  if (!alt || (alt.frame || 'robot') === 'robot') return 'robot';
  const I = need(inst);
  try {
    const a = anchorOf(slotId, I);
    if (a && a.name && a.matrix) return a.name;
  } catch (e) { /* fall through */ }
  return 'robot';
}

export function importOption(slotId, geometry, name, opts = {}, inst) {
  const I = need(inst);
  const slot = I.slots[slotId];
  if (!slot) throw new Error(`slots: unknown slot "${slotId}"`);
  const anchor = anchorOf(slotId, I);
  const base = anchor.matrix ? anchor.matrix.clone() : new Matrix4();

  const bb = geometryBBox(geometry);
  let fit = opts.fit || (anchor.data && anchor.data.fit) || (anchor.parent === 'world' ? 'base_centre' : 'origin');
  if (fit === 'auto') {
    fit = 'base_centre';
    const o = new Vector3().setFromMatrixPosition(base);
    if (bb && anchor.parent === 'world') {
      const cx = (bb.min[0] + bb.max[0]) / 2, cy = (bb.min[1] + bb.max[1]) / 2;
      const near = Math.hypot(cx - o.x, cy - o.y) < 60;
      const straddles = bb.min[2] <= o.z + 1 && bb.max[2] > o.z;
      if (near && straddles) fit = 'origin';
    }
  }
  let offset = [0, 0, 0];
  if (fit === 'base_centre' && bb) offset = [-(bb.min[0] + bb.max[0]) / 2, -(bb.min[1] + bb.max[1]) / 2, -bb.min[2]];
  const transform = base.multiply(new Matrix4().makeTranslation(offset[0], offset[1], offset[2]));

  const st = geometryStats(geometry);
  const id = slug(opts.id || name || slotId, slotId + '_import');
  return {
    schema: 'rps/assembly@1#part', id,
    source: { kind: 'file', name: name || id + '.stl', sha1: opts.sha1 || null, bytes: opts.bytes || null },
    parent: opts.parent || anchor.parent || 'world',
    transform: transform.toArray(),
    color: opts.color || '#c98a3c', visible: true, locked: false,
    meta: {
      bbox_local: bb ? [bb.min.slice(), bb.max.slice()] : null,
      volume_cm3: st.volume_cm3, faces: st.faces,
      placement: { slot: slotId, anchor: slot.anchor, fit, offset_mm: offset, frame: anchor.source },
    },
    slot: slotId, option: 'import',
    note: `Imported into slot "${slot.label}" at anchor "${slot.anchor}" (${anchor.source})`,
  };
}
